export function createOfficeControls({getView,onSubmitted}){
  const $=s=>document.querySelector(s),dialog=$('#command-dialog');let target=null,sending=false;
  dialog.innerHTML=`<form id="task-editor"><div class="dialog-heading"><h2 id="editor-title">添加任务</h2><button type="button" id="editor-close" aria-label="关闭">×</button></div>
    <label class="command-field">任务名称<input id="editor-name" maxlength="300" required></label>
    <label class="command-field">项目<input id="editor-project" maxlength="200" value="我的项目"></label>
    <label class="command-field">工具 / 来源<input id="editor-provider" maxlength="80" placeholder="手动 / Claude Code / Cursor / 自建工具"></label>
    <div class="portable-fields"><label>状态<select id="editor-status"><option value="working">进行中</option><option value="waiting">待处理</option><option value="idle">空闲</option><option value="done">已完成</option><option value="error">出错</option><option value="unknown">未确认</option></select></label>
    <label>部门<select id="editor-role"><option value="engineering">工程</option><option value="design">设计</option><option value="research">研究</option><option value="writing">编审与写作</option><option value="pr">公关</option><option value="sales">销售</option><option value="planning">策划</option><option value="operations">运营与行政</option></select></label></div>
    <label class="command-field">任务链接（可选）<input id="editor-url" type="url" maxlength="2048" placeholder="https://..."></label>
    <label class="command-field">说明 / 已交付内容<textarea id="editor-reply" rows="4" maxlength="65536"></textarea></label>
    <p class="settings-help">这里只管理展示的任务；保存状态不会启动、停止或宣称完成其他 AI 工具的工作。</p>
    <p id="editor-message" role="status"></p><div class="slap-actions"><button class="primary-button" type="submit" id="editor-save">保存任务</button><button type="button" id="editor-delete">删除任务</button><button type="button" id="clear-samples">移除示例任务</button></div></form>`;
  const feedback=document.createElement('dialog');feedback.id='portable-feedback';feedback.innerHTML=`<form id="feedback-form"><div class="dialog-heading"><h2>返工要求</h2><button type="button" id="feedback-close">×</button></div><p id="feedback-target"></p><textarea id="feedback-text" rows="6" maxlength="8000" required></textarea><p class="settings-help">未配置接收器时只记录在本机；接收器接受请求不代表 AI 已执行。</p><p id="feedback-message" role="status"></p><button class="primary-button" id="feedback-send">发送到接收器 / 本机记录</button></form>`;document.body.append(feedback);
  let feedbackTask=null,lastRequest=null;
  const createButton=document.createElement('button');createButton.id='portable-add-task';createButton.className='quiet-button';createButton.textContent='添加任务';createButton.onclick=()=>open();$('.header-tools').prepend(createButton);
  const fields={title:$('#editor-name'),project:$('#editor-project'),provider:$('#editor-provider'),status:$('#editor-status'),roleHint:$('#editor-role'),url:$('#editor-url'),reply:$('#editor-reply')};
  async function request(method,input){const response=await fetch('/api/tasks',{method,headers:{'Content-Type':'application/json','X-Workroom-Action':'tasks'},body:JSON.stringify(input)});const result=await response.json();if(!response.ok)throw Error(result.message||result.error||'保存失败');return result;}
  function open(task){target=task||null;$('#editor-title').textContent=task?'编辑任务':'添加任务';for(const [key,node] of Object.entries(fields))node.value=task?.[key]??({project:'我的项目',provider:'手动',status:'working',roleHint:'engineering'}[key]||'');$('#editor-message').textContent='';$('#editor-delete').hidden=!task;dialog.showModal();fields.title.focus();}
  $('#editor-close').onclick=()=>{if(!sending)dialog.close();};
  $('#task-editor').onsubmit=async event=>{event.preventDefault();if(sending)return;sending=true;$('#editor-save').disabled=true;try{const input=Object.fromEntries(Object.entries(fields).map(([key,node])=>[key,node.value]));if(target)input.id=target.id;const result=await request('POST',input);await onSubmitted?.(result);dialog.close();}catch(e){$('#editor-message').textContent=e.message;}finally{sending=false;$('#editor-save').disabled=false;}};
  $('#editor-delete').onclick=async()=>{if(!target||sending)return;sending=true;try{await request('DELETE',{id:target.id});await onSubmitted?.({taskId:null});dialog.close();}catch(e){$('#editor-message').textContent=e.message;}finally{sending=false;}};
  $('#clear-samples').onclick=async()=>{if(sending)return;sending=true;try{const samples=getView().tasks.filter(t=>t.sample);for(const task of samples)await request('DELETE',{id:task.id});await onSubmitted?.({taskId:null});$('#editor-message').textContent='已移除示例；可以添加真实任务或让自己的工具通过文件 / CLI / HTTP 发布。';}catch(e){$('#editor-message').textContent=e.message;}finally{sending=false;}};
  $('#feedback-close').onclick=()=>feedback.close();
  $('#feedback-form').onsubmit=async event=>{event.preventDefault();if(!feedbackTask||sending)return;sending=true;$('#feedback-send').disabled=true;try{const text=$('#feedback-text').value.trim(),fingerprint=JSON.stringify([feedbackTask.id,text]);if(lastRequest?.fingerprint!==fingerprint)lastRequest={fingerprint,id:crypto.randomUUID()};const r=await fetch('/api/instructions',{method:'POST',headers:{'Content-Type':'application/json','X-Workroom-Action':'instruction'},body:JSON.stringify({taskId:feedbackTask.id,text,requestId:lastRequest.id})});const result=await r.json();$('#feedback-message').textContent=r.ok?(result.status==='accepted-by-adapter'?'接收器已接受；实际执行请在原工具核对。':'仅记录在本机，尚未连接外部工具。'):result.error==='busy'?'任务进行中；请等任务结束后发送。':result.error==='outcome_unknown'?'发送结果未知，不会自动重发；请先核对接收器。':'发送失败：'+result.error;}catch{$('#feedback-message').textContent='发送结果未知；保留同一事件 ID，先核对接收器。';}finally{sending=false;$('#feedback-send').disabled=false;}};
  function refreshText(){ $('#codex-usage').hidden=true;$('#command-heading').textContent='任务管理';$('#command-new').textContent='添加任务';$('#command-continue').textContent='编辑所选任务';refreshTask();}
  function refreshTask(){const view=getView(),task=view.tasks.find(t=>t.id===view.selected);$('#command-continue').disabled=!task;$('#command-new').disabled=false;$('#command-context').textContent=task?task.title:'添加任务，或通过文件 / CLI / HTTP 接入自己的工具';$('#command-handoff').hidden=true;}
  $('#command-new').onclick=()=>open();$('#command-continue').onclick=()=>open(getView().tasks.find(t=>t.id===getView().selected));
  refreshText();return {refreshText,refreshTask,refreshUsage(){},draftFeedback(task,text){feedbackTask=task;lastRequest=null;$('#feedback-target').textContent=task.title;$('#feedback-text').value=text;$('#feedback-message').textContent=task.sample?'示例任务不能向外部工具发送返工要求。':'';$('#feedback-send').disabled=task.sample===true;feedback.showModal();},destroy(){feedback.remove();createButton.remove();}};
}
